const MAX_AUDIO = 12 * 1024 * 1024;
const COURSE_MAP: Record<string,string> = {
  "thajweedh":"THAJ",
  "quranic-arabic-ladies":"QA",
  "quranic-arabic-teenagers":"QA",
  "quranic-arabic-adults":"QA",
  "quranic-words-young-hearts":"QAYH",
  "quranic-arabic-young-hearts-1":"QAYH",
  "quranic-arabic-young-hearts-2":"QAYH",
  "quranic-arabic-young-hearts-3":"QAYH",
  "basic-islamic-studies":"BIS",
  "intermediary-islamic-studies":"IIS",
  "quran-halqa":"HLQ",
  "quran-revert-sisters":"RVT"
};

function cors(req: Request) {
  const origin = req.headers.get("origin") || "";
  const allowed = new Set([
    "https://intake.quranarabicjournal.com",
    "https://raw.githack.com",
    "https://viajmvbwpmkiqxjtgshv.supabase.co"
  ]);
  const allowOrigin = allowed.has(origin) ? origin : "https://intake.quranarabicjournal.com";
  return {
    "Access-Control-Allow-Origin": allowOrigin,
    "Vary": "Origin",
    "Access-Control-Allow-Headers": "content-type, authorization, apikey, x-client-info",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS"
  };
}
function responsePage(title:string,message:string,ok:boolean) {
  const accent=ok ? "#096a65" : "#b42318";
  const symbol=ok ? "✓" : "!";
  const safeTitle=title.replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;");
  const safeMessage=message.replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#3b132b"><title>${safeTitle}</title><style>*{box-sizing:border-box}body{margin:0;min-height:100dvh;display:grid;place-items:center;padding:24px;color:#25161f;background:#fff4df;font:16px/1.5 system-ui,-apple-system,sans-serif}.card{width:min(560px,100%);padding:28px;background:#fff;border:1px solid #e7d8ce;border-top:7px solid ${accent};border-radius:16px;box-shadow:0 18px 45px rgba(59,19,43,.12)}.mark{width:54px;height:54px;display:grid;place-items:center;border-radius:50%;color:white;background:${accent};font-size:28px;font-weight:700}h1{margin:18px 0 8px;font:600 34px/1.05 Georgia,serif}p{margin:0 0 20px;color:#74666e}a{min-height:48px;display:inline-flex;align-items:center;justify-content:center;padding:10px 16px;color:white;background:#3b132b;border-radius:6px;text-decoration:none;font-weight:700}</style></head><body><main class="card"><div class="mark">${symbol}</div><h1>${safeTitle}</h1><p>${safeMessage}</p><a href="https://intake.quranarabicjournal.com/">Back to QAJ registration</a></main></body></html>`;
}

function json(req: Request,status:number,body:Record<string,unknown>) {
  const transport = new URL(req.url).searchParams.get("transport");

  if (transport === "native") {
    const result = status >= 200 && status < 300 && body.ok === true ? "ok" : "error";
    const params = new URLSearchParams({qaj_submit:result});
    if (result === "error" && typeof body.error === "string") params.set("message", body.error.slice(0,180));
    if (result === "ok" && typeof body.id === "string") params.set("id", body.id);
    return new Response(null,{
      status:303,
      headers:{
        "Location":"https://intake.quranarabicjournal.com/?"+params.toString(),
        "Cache-Control":"no-store"
      }
    });
  }

  if (transport === "page") {
    const ok = status >= 200 && status < 300 && body.ok === true;
    const title = ok ? "Registration received" : "Registration not completed";
    const message = ok
      ? "Jazakillahu khairan. QAJ has received your registration and payment receipt."
      : (typeof body.error === "string" ? body.error : "We could not complete the registration. Please go back and try again.");
    return new Response(responsePage(title,message,ok),{
      status:ok ? 200 : Math.max(400,status),
      headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store"}
    });
  }

  return new Response(JSON.stringify(body),{status,headers:{...cors(req),"content-type":"application/json","cache-control":"no-store"}});
}
function ext(name:string){
  const clean=(name||"").trim();
  return (clean.includes(".")?clean.split(".").pop():"bin")!.toLowerCase();
}
function buildMeta(fd:FormData){
  const excluded=new Set(["course_code","full_name","dob","address","phone","whatsapp","instagram","emergency_contact","country_birth","country_residency","email","class_mode","class_location","available_days","time_from_12h","time_to_12h","registration_type","relationship","child_notes","course_meta","payment_receipt","test_me_audio","data_correct","first_registration","submission_id"]);
  const meta:Record<string,unknown>={};
  for(const [k,v] of fd.entries()){
    if(excluded.has(k)||v instanceof File) continue;
    const raw=String(v);
    let parsed:unknown=raw;
    const t=raw.trim();
    if((t.startsWith("{")&&t.endsWith("}"))||(t.startsWith("[")&&t.endsWith("]"))){
      try{parsed=JSON.parse(t)}catch{}
    }
    if(Object.prototype.hasOwnProperty.call(meta,k)){
      meta[k]=Array.isArray(meta[k])?[...(meta[k] as unknown[]),parsed]:[meta[k],parsed];
    }else meta[k]=parsed;
  }
  return meta;
}
Deno.serve(async (req:Request)=>{
  if(req.method==="OPTIONS") return new Response("ok",{headers:cors(req)});
  if(req.method==="GET") {
    return new Response(PAGE,{status:200,headers:{...cors(req),"content-type":"text/html; charset=utf-8","cache-control":"no-store","x-robots-tag":"noindex"}});
  }
  if(req.method!=="POST") return json(req,405,{ok:false,error:"Method not allowed"});

  try{
    const origin=req.headers.get("origin")||"";
    const allowedOrigins=["https://intake.quranarabicjournal.com","https://raw.githack.com","https://viajmvbwpmkiqxjtgshv.supabase.co"];
    if(origin && !allowedOrigins.includes(origin)) return json(req,403,{ok:false,error:"Origin not allowed"});

    const ct=req.headers.get("content-type")||"";
    if(!ct.includes("multipart/form-data")) return json(req,400,{ok:false,error:"Expected multipart/form-data"});

    const url=Deno.env.get("SUPABASE_URL");
    const key=Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
    if(!url||!key) return json(req,500,{ok:false,error:"Server configuration missing"});
    const supabase=createClient(url,key,{auth:{persistSession:false}});

    const fd=await req.formData();
    const submittedId=String(fd.get("submission_id")||"").trim();
    const validSubmittedId=/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(submittedId);
    const registrationId=validSubmittedId ? submittedId : crypto.randomUUID();
    const rawCourse=String(fd.get("course_code")||"").trim();
    const course_code=COURSE_MAP[rawCourse]||rawCourse;
    const full_name=String(fd.get("full_name")||"").trim();
    const dob=String(fd.get("dob")||"").trim();
    const address=String(fd.get("address")||"").trim();
    const phone=String(fd.get("phone")||"").trim();
    const whatsapp=String(fd.get("whatsapp")||"").trim();
    const emergency_contact=String(fd.get("emergency_contact")||"").trim();
    const country_birth=String(fd.get("country_birth")||"").trim();
    const country_residency=String(fd.get("country_residency")||"").trim();
    const email=String(fd.get("email")||"").trim();
    const registration_type=String(fd.get("registration_type")||"").trim();
    const data_correct=fd.has("data_correct");

    if(!rawCourse||!full_name||!dob||!address||!phone||!whatsapp||!emergency_contact||!country_birth||!country_residency||!email||!registration_type||!data_correct){
      return json(req,400,{ok:false,error:"Please complete all required fields and confirmations."});
    }
    const relationship=String(fd.get("relationship")||"").trim()||null;
    if(registration_type==="other"&&!relationship) return json(req,400,{ok:false,error:"Relationship is required."});

    const payment=fd.get("payment_receipt");
    if(!(payment instanceof File)||payment.size===0) return json(req,400,{ok:false,error:"Payment receipt is required."});
    if(payment.size>MAX_RECEIPT) return json(req,400,{ok:false,error:"Payment receipt must be 6 MB or smaller."});
    if(!(payment.type.startsWith("image/")||payment.type==="application/pdf")) return json(req,400,{ok:false,error:"Payment receipt must be an image or PDF."});

    const audio=fd.get("test_me_audio");
    if(audio instanceof File && audio.size>MAX_AUDIO) return json(req,400,{ok:false,error:"Audio file must be 12 MB or smaller."});

    const instagram=String(fd.get("instagram")||"").trim()||null;
    const class_mode=String(fd.get("class_mode")||fd.get("qa_class_mode")||fd.get("yh_class_mode")||"").trim()||null;
    const class_location=String(fd.get("class_location")||fd.get("qa_physical_location")||fd.get("yh_physical_location")||"").trim()||null;
    const time_from_12h=String(fd.get("time_from_12h")||"").trim()||null;
    const time_to_12h=String(fd.get("time_to_12h")||"").trim()||null;
    const first_registration=fd.has("first_registration");
    const available_days=fd.getAll("available_days").map(String);
    const child_notes=fd.getAll("child_notes").map(String);

    const course_meta={...buildMeta(fd),selected_course_id:rawCourse,submission_id:registrationId};

    const insertPayload={
      id:registrationId,
      course_code,full_name,dob,address,phone,whatsapp,instagram,emergency_contact,country_birth,country_residency,email,
      class_mode,class_location,available_days,time_from_12h,time_to_12h,registration_type,relationship,child_notes,
      data_correct,first_registration,course_meta,source:"intake_2026_web",intake_status:"pending"
    };

    let {data:row,error:insertError}=await supabase
      .from("qaj_course_registrations")
      .insert(insertPayload)
      .select("id,payment_receipt_path,test_me_audio_path")
      .single();

    if(insertError || !row){
      if(insertError?.code === "23505"){
        const {data:existing,error:existingError}=await supabase
          .from("qaj_course_registrations")
          .select("id,payment_receipt_path,test_me_audio_path")
          .eq("id",registrationId)
          .maybeSingle();
        if(existingError || !existing){
          return json(req,500,{ok:false,error:"Could not confirm the existing registration. Please try again."});
        }
        row=existing;
      } else {
        return json(req,500,{ok:false,error:"Could not save registration."});
      }
    }

    const id=row.id as string;
    const warnings:string[]=[];
    let payment_receipt_path=(row.payment_receipt_path as string | null) || null;
    let test_me_audio_path=(row.test_me_audio_path as string | null) || null;

    const uploadTasks:Promise<void>[]=[];

    if(!payment_receipt_path){
      const pPath=`registrations/${id}/payment_receipt.${ext(payment.name)}`;
      uploadTasks.push((async()=>{
        const {error}=await supabase.storage.from(BUCKET).upload(pPath,payment,{upsert:true,contentType:payment.type||undefined});
        if(error) warnings.push("payment receipt upload failed");
        else payment_receipt_path=pPath;
      })());
    }

    if(audio instanceof File && audio.size>0 && !test_me_audio_path){
      const aPath=`registrations/${id}/test_me_audio.${ext(audio.name)}`;
      uploadTasks.push((async()=>{
        const {error}=await supabase.storage.from(BUCKET).upload(aPath,audio,{upsert:true,contentType:audio.type||undefined});
        if(error) warnings.push("audio upload failed");
        else test_me_audio_path=aPath;
      })());
    }

    if(uploadTasks.length) await Promise.allSettled(uploadTasks);

    const {error:updateError}=await supabase
      .from("qaj_course_registrations")
      .update({payment_receipt_path,test_me_audio_path})
      .eq("id",id);
    if(updateError) warnings.push("registration file-path update failed");

    if(!payment_receipt_path){
      return json(req,500,{
        ok:false,
        error:"Registration details were saved, but the payment receipt did not upload. Your retry is safe and will not create a duplicate registration.",
        id,
        warnings
      });
    }

    return json(req,200,{ok:true,id,warnings});
  }catch(e){
    console.error("qaj-intake-live error",e);
    return json(req,500,{ok:false,error:"Server error. Please try again."});
  }
});